#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1" opener="" c
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  for c in wslview explorer.exe xdg-open open; do
    command -v "$c" >/dev/null 2>&1 && { opener=$c; break; }
  done
  if [[ -z "$opener" || ( "$opener" == xdg-open && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ) ]]; then
    warn "couldn't open a browser; visit it manually: $url"
    return 0
  fi
  # Detached: xdg-open waits on a browser it had to start (an AppImage, say) until that browser quits.
  ( "$opener" "$url" </dev/null >/dev/null 2>&1 & )
  note "if no tab opened, visit it manually"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Cairn phase 3. Run on the Beelink (an SSH session from the MacBook is fine). The first two
# stages close holes the product review of 2026-11-09 found, before phase 3 deploys anything; the
# plan's own steps (docs/phase-3/plan.md, section 6) add their stages after them.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=2

REPO=$(cd "$(dirname "$0")/../.." && pwd)
cd "$REPO"
# This wizard captures no secret. The CI token goes from Cloudflare to GitHub inside Alchemy and is
# never shown; the admin profile's key stays in ~/.alchemy and is never read here.
mkdir -p ~/.config/cairn && chmod 700 ~/.config/cairn
ENV_FILE=~/.config/cairn/phase-3.env
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"
VERDICTS=~/.config/cairn/phase-3-verdicts.txt
# Re-run from a later stage with `ops/wizards/phase-3.sh <stage>`.
FROM_STAGE=${1:-1}
want() { (( $1 >= FROM_STAGE )) || { _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; }; }
# One line per verdict: date, stage, result, then free text.
record() { printf '%s stage=%s %s\n' "$(date -Is)" "$1" "$2" >>"$VERDICTS"; }

banner "Cairn phase 3: before anything deploys"

# ── 1 ─────────────────────────────────────────────────────────────────────
# The owner-only guard and stream_close_delay, split out of phase 2's shelved reach stage
# (ops/wizards/phase-2.sh stage 2): neither needs porch. ADR 0038 says plans.gneiss.run is
# owner-only; until this stage runs it serves every agent page, with a directory listing, to every
# device that reaches Caddy. Both edits are ops/wizards/reach-edits.ts's, shown as a diff and applied
# only on yes, to a candidate beside the live Caddyfile that Caddy validates and fmt-checks inside
# the live container before it is installed. The live Caddyfile is backed up first.
if want 1; then
  stage "plans.gneiss.run becomes yours alone (ADR 0038)"
  say "Every plan, report and review an agent writes for you is served at plans.gneiss.run."
  say "Today any device that reaches your Caddy can browse them: a friend's phone on the"
  say "tailnet, or anything on the LAN. This stage puts them behind Cairn's owner check, the"
  say "same one code.gneiss.run uses, and adds stream_close_delay so a Caddy reload stops"
  say "cutting open WebSockets (Cairn's, t3code's, Home Assistant's)."
  warn "The cost: a plan link you shared with someone else stops opening for them."
  note "Only you, by Tailscale identity, get a page. A LAN device, another person's device and a"
  note "tagged node get 403, and while the brain on 3774 is down, plans do not open either."
  note "Not covered: exec.gneiss.run. This guard names plans and portal hosts only. Guarding"
  note "Executor needs an exception for the docker bridge (its container calls itself from"
  note "172.17.0.x), so it stays a separate decision (review finding E-5)."

  CADDY_DIR=~/caddy
  CADDYFILE=$CADDY_DIR/conf/Caddyfile
  CANDIDATE=$CADDY_DIR/conf/Caddyfile.owner-candidate
  STAMP=$(date +%Y%m%d-%H%M%S)
  OWNER_OK=1
  GUARD_RESULT=not-run
  CLOSE_DELAY=not-run
  PHONE_RESULT=not-run
  in_caddy() { docker exec caddy caddy "$@"; }

  # apply_edit EDIT FILE: computes EDIT on FILE, shows the diff, and writes it back on yes.
  # Answers 0 when FILE now holds the edit (or needed none), 1 when it was declined or refused.
  apply_edit() {
    local edit=$1 file=$2 next="$2.next"
    if ! node ops/wizards/reach-edits.ts "$edit" "$file" "$next"; then
      rm -f "$next"
      warn "$edit: not applied (the reason is above)."
      return 1
    fi
    if cmp -s "$file" "$next"; then
      rm -f "$next"
      return 0
    fi
    printf '\n'
    diff -u "$file" "$next" | tail -n +3 || true
    printf '\n'
    if confirm "Apply this $edit edit"; then
      cat "$next" >"$file"
      rm -f "$next"
      return 0
    fi
    rm -f "$next"
    warn "$edit declined"
    return 1
  }

  pause "Press Enter to see the edits (nothing changes until you say yes)"

  # 1a. The backup, before anything is touched.
  if [[ ! -f $CADDYFILE ]]; then
    warn "No $CADDYFILE: this stage expects the Docker Caddy in ~/caddy."
    OWNER_OK=0
  elif [[ $(docker inspect -f '{{.State.Running}}' caddy 2>/dev/null || echo false) != true ]]; then
    warn "The caddy container is not running; start it (cd ~/caddy && docker compose up -d) and re-run."
    OWNER_OK=0
  else
    cp "$CADDYFILE" "$CADDYFILE.bak-before-owner-only-$STAMP"
    printf '  %s✓ backed up%s %s (.bak-before-owner-only-%s)\n' "$GREEN" "$RESET" "$CADDYFILE" "$STAMP"
  fi

  # 1b. The two edits, on a candidate, validated and fmt-checked by the live Caddy.
  if ((OWNER_OK)); then
    cp "$CADDYFILE" "$CANDIDATE"
    GUARD_IN=0
    if apply_edit owner-only "$CANDIDATE"; then GUARD_IN=1; fi
    apply_edit stream-close-delay "$CANDIDATE" || true
    if ((!GUARD_IN)); then
      warn "Without the owner-only edit this stage changes nothing; the live Caddyfile is unchanged."
      GUARD_RESULT=declined
      OWNER_OK=0
    elif cmp -s "$CADDYFILE" "$CANDIDATE"; then
      note "The Caddyfile already holds both edits."
    elif ! in_caddy validate --config /etc/caddy/Caddyfile.owner-candidate --adapter caddyfile; then
      warn "Caddy refused the candidate; the live Caddyfile is unchanged."
      OWNER_OK=0
    elif ! in_caddy fmt /etc/caddy/Caddyfile.owner-candidate | diff -q - "$CANDIDATE" >/dev/null; then
      warn "The candidate is not caddy fmt clean; the live Caddyfile is unchanged."
      OWNER_OK=0
    elif confirm "Install the candidate as the live Caddyfile and reload Caddy"; then
      cat "$CANDIDATE" >"$CADDYFILE"
      in_caddy reload --config /etc/caddy/Caddyfile --adapter caddyfile || OWNER_OK=0
    else
      OWNER_OK=0
    fi
    rm -f "$CANDIDATE"
  fi

  # 1c. The outside judges. From the Beelink itself through 127.0.0.1: Cairn refuses loopback
  # peers, so a guarded plans host answers 403 in any letter case, and a 200 means the guard lets
  # that host past it. Then the live close delay (read-only), then you, from the phone.
  if ((OWNER_OK)); then
    GUARD_RESULT=pass
    for host in plans.gneiss.run PLANS.gneiss.run; do
      set +e
      GUARD_STATUS=$(curl -sk -o /dev/null -w '%{http_code}' --resolve plans.gneiss.run:443:127.0.0.1 -H "Host: $host" https://plans.gneiss.run/cairn/)
      set -e
      if [[ $GUARD_STATUS != 403 ]]; then
        warn "Host: $host through 127.0.0.1 answered $GUARD_STATUS, not 403: the owner-only guard does not hold."
        GUARD_RESULT=fail
      fi
    done
    [[ $GUARD_RESULT == pass ]] && printf '  %s✓ the guard refuses a peer that is not you%s\n' "$GREEN" "$RESET"

    if node judges/caddy-reload.ts --live; then CLOSE_DELAY=pass; else CLOSE_DELAY=fail; fi

    say ""
    step "On your phone, signed in to the tailnet as you, open ${BOLD}https://plans.gneiss.run/cairn/${RESET}"
    if confirm "Did it list the cairn folder"; then PHONE_RESULT=pass; else PHONE_RESULT=fail; fi
    [[ $GUARD_RESULT == pass && $PHONE_RESULT == pass ]] || OWNER_OK=0
  fi

  if ((OWNER_OK)); then
    record 1 "owner-only=pass guard=$GUARD_RESULT close_delay=$CLOSE_DELAY phone=$PHONE_RESULT backup=$STAMP"
    printf '  %s✓ plans.gneiss.run is yours alone%s\n' "$GREEN" "$RESET"
    [[ $CLOSE_DELAY == pass ]] || SKIPPED+=("stage 1: the close delay check failed (node judges/caddy-reload.ts --live); the guard holds")
  else
    record 1 "owner-only=fail guard=$GUARD_RESULT close_delay=$CLOSE_DELAY phone=$PHONE_RESULT backup=$STAMP"
    note "Backup: $CADDYFILE.bak-before-owner-only-$STAMP"
    note "To put it back: cat <backup> > $CADDYFILE, then docker exec caddy caddy reload --config /etc/caddy/Caddyfile --adapter caddyfile"
    SKIPPED+=("stage 1: plans.gneiss.run owner-only (ops/wizards/phase-3.sh 1)")
  fi
  pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
# ADR 0051: the CI token cairn-ci loses every right but Workers Containers Write. Alchemy updates the
# token in place (its value, and so the GitHub secret, stay the same), under the admin profile. Then
# the stone image workflow, the token's only reader, runs once to prove the narrower token still
# pushes. The admin profile holds the Cloudflare Global API Key; whether to keep it is yours.
if want 2; then
  stage "CI token: registry pushes only (ADR 0051)"
  say "GitHub Actions holds a Cloudflare token, cairn-ci, minted by stacks/github.ts. Its one job"
  say "is pushing the stone image to Cloudflare's registry, yet it can also write every Worker,"
  say "the Secrets Store and account settings. This stage cuts it to Workers Containers Write."
  note "Alchemy updates the token in place: its value and the GitHub secret stay the same."
  note "If this is the account's first Alchemy beta.85 run, Alchemy moves its shared state store"
  note "to v8. Every stack and spike in the repo is on beta.85 now, so that is expected."
  CI_DEPLOY=not-run
  CI_PUSH=not-run
  ADMIN_PROFILE=kept
  say ""
  say "The deploy needs the ${BOLD}admin${RESET} Alchemy profile (your Global API Key and the GitHub CLI)."
  # Profile names and their providers only; a piped listing is plain text and holds no key.
  PROFILES=$(pnpm exec alchemy profile list </dev/null 2>/dev/null || true)
  if grep -Eq '^[-*] admin(:|$)' <<<"$PROFILES"; then
    note "The admin profile exists."
  else
    note "There is no admin profile (ops/wizards/phase-0.sh deletes it after its own deploy)."
    note "This stage makes it again, as phase 0 stage 6 does."
    open_url "https://dash.cloudflare.com/profile/api-tokens"
    step "Under API Keys → Global API Key → View. Keep the page open."
    step "Next, Alchemy asks how to sign in to Cloudflare: choose ${BOLD}API Token or API Key${RESET},"
    say "    then the Global API Key, and paste the key and your Cloudflare email when asked."
    step "Then it adds GitHub: choose ${BOLD}GitHub CLI${RESET} (gh is already logged in)."
    pause "Press Enter to start Alchemy's prompts"
    pnpm exec alchemy profile create admin 2>/dev/null || note "profile admin already exists; editing it"
    pnpm exec alchemy profile edit --profile admin --add Cloudflare --add GitHub
  fi
  if confirm "Deploy stacks/github.ts under the admin profile now (Alchemy shows its plan and asks first)"; then
    if pnpm exec alchemy deploy --config stacks/github.ts --profile admin; then
      CI_DEPLOY=pass
    else
      CI_DEPLOY=fail
      warn "The deploy failed (see above); the token keeps its old rights."
    fi
  else
    CI_DEPLOY=declined
  fi

  if [[ $CI_DEPLOY == pass ]]; then
    open_url "https://dash.cloudflare.com/?to=/:account/api-tokens"
    step "Find ${BOLD}cairn-ci${RESET} under the account's API tokens. Its permissions should be one line:"
    say "    Workers Containers, Edit. Nothing for Workers Scripts, Secrets Store or Account Settings."
    if confirm "Does cairn-ci show only that permission"; then
      say ""
      say "Last, the proof: the stone image workflow logs in to the registry with the narrowed token"
      say "and pushes (a few minutes on GitHub's runners, nothing on the Beelink)."
      if confirm "Run the stone image workflow on GitHub now and watch it"; then
        # Watch the run this dispatch made, never an older one: note the newest dispatched run
        # first, then wait for a newer one to be listed.
        LAST_RUN=$(gh run list --repo oscabriel/cairn --workflow stone-image.yml --event workflow_dispatch --limit 1 --json databaseId -q '.[0].databaseId // ""' || true)
        RUN_ID=""
        if gh workflow run stone-image.yml --repo oscabriel/cairn --ref main; then
          note "Waiting for the run to appear..."
          for _ in $(seq 1 30); do
            sleep 3
            RUN_ID=$(gh run list --repo oscabriel/cairn --workflow stone-image.yml --event workflow_dispatch --limit 1 --json databaseId -q '.[0].databaseId // ""' || true)
            [[ -n $RUN_ID && $RUN_ID != "$LAST_RUN" ]] && break
            RUN_ID=""
          done
          if [[ -z $RUN_ID ]]; then
            CI_PUSH=fail
            warn "The dispatched run did not appear within 90 s; see https://github.com/oscabriel/cairn/actions"
          elif gh run watch "$RUN_ID" --repo oscabriel/cairn --exit-status; then
            CI_PUSH=pass
          else
            CI_PUSH=fail
            warn "The workflow failed. If its registry login step was refused, the token needs one more"
            warn "permission: tell Claude that step's error rather than restoring the old rights."
          fi
        else
          CI_PUSH=fail
        fi
      else
        CI_PUSH=declined
      fi
    else
      CI_DEPLOY=wrong-scope
    fi
  fi

  say ""
  say "The admin profile still holds your Cloudflare Global API Key, which can do anything on"
  say "the account. It is needed only when the CI token changes again, and this stage makes it"
  say "again in a minute when it is missing."
  if confirm "Delete the admin profile now"; then
    if pnpm exec alchemy profile delete admin --yes; then
      ADMIN_PROFILE=deleted
    else
      ADMIN_PROFILE=delete-failed
      warn "It may not exist, or the delete failed: pnpm exec alchemy profile list shows the profiles."
    fi
  fi

  record 2 "ci_deploy=$CI_DEPLOY ci_push=$CI_PUSH admin_profile=$ADMIN_PROFILE"
  if [[ $CI_DEPLOY == pass && $CI_PUSH == pass ]]; then
    printf '  %s✓ cairn-ci can push images and nothing else%s\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("stage 2: narrow the CI token (ops/wizards/phase-3.sh 2): deploy=$CI_DEPLOY push=$CI_PUSH")
  fi
  pause
fi

finish
say "Verdicts are in $VERDICTS. Tell Claude the wizard is done."
printf '\n'
